sp_widget.client_script:
api.controller=function($location) {
    var c = this;

    // ---------------------------------------------------------
    // Navigation: routes to the correct page and tracks which
    // nav item is "active" for highlighting.
    // ---------------------------------------------------------
    c.goTo = function(pageId, navKey) {
        c.data.currentPage = navKey;
        $location.path('/' + pageId);
    };

    // ---------------------------------------------------------
    // Logout: uses Service Portal's native logout mechanism.
    // No backend widget logic needed — this is a platform action.
    // ---------------------------------------------------------
    c.logout = function() {
        window.location.href = '/logout.do';
    };
}

sp_widget.css:
.cfa-sidebar-nav{
  display:flex;
  flex-direction:column;
  gap:4px;
  padding:12px;
}
.cfa-nav-item{
  display:flex;
  align-items:center;
  gap:10px;
  padding:11px 14px;
  border-radius:10px;
  border:none;
  background:none;
  color:#cbd5e1;
  font-size:14px;
  font-weight:600;
  cursor:pointer;
  text-align:left;
  width:100%;
}
.cfa-nav-item:hover{
  background:#1e293b;
  color:#fff;
}
.cfa-nav-item.active{
  background:#0d9488;
  color:#fff;
}
.cfa-nav-ic{
  font-size:16px;
}

.cfa-sidebar-footer{
  padding:16px;
  border-top:1px solid #1e293b;
  margin-top:auto;
}
.cfa-side-user b{
  color:#fff;
  display:block;
  font-size:13.5px;
}
.cfa-side-user span{
  font-size:12px;
  color:#94a3b8;
}
.cfa-btn-logout{
  width:100%;
  margin-top:10px;
  background:#1e293b;
  color:#cbd5e1;
  border:1px solid #334155;
  border-radius:8px;
  padding:9px;
  cursor:pointer;
  font-size:12.5px;
}
.cfa-btn-logout:hover{
  background:#dc2626;
  color:#fff;
}

sp_widget.script:
(function() {

    // ---------------------------------------------------------
    // FRONTEND-ONLY STUB: nav items are hardcoded here for now
    // since we're building the visual/layout first, backend
    // logic comes later.
    //
    // WHEN BACKEND IS WIRED, THIS BLOCK SHOULD INSTEAD:
    //   1. Check gs.hasRole('x_cfsa_student') — if false, this
    //      widget shouldn't render these items at all
    //   2. Build data.navItems as an array the server decides,
    //      e.g. only include "Raise a Request" if the student's
    //      u_student record is active, etc.
    //   3. Any future lock/unlock logic (like the earlier
    //      Feedback-locked pattern) would compute a boolean
    //      here — e.g. data.feedbackAvailable = <GlideRecord
    //      check> — and the HTML would read that flag, not
    //      decide it client-side.
    // ---------------------------------------------------------

    data.userName = gs.getUser().getDisplayName();
    data.userMeta = 'Student'; // later: pull roll number / hostel from x_snc_campus_foo_1_student

    // currentPage would ideally come from the page context itself
    // rather than being passed in — placeholder for now
    data.currentPage = input.currentPage || 'dashboard';

})();
